# middleware/tests/test_transform.py
import json, subprocess, sys
import pytest
from tools.transform import webhook_to_donation, UnsupportedEvent

@pytest.fixture
def event():
    return json.load(open('checks/m0/golden/sample_event.json'))  # or build a dict inline

def test_golden(event):
    assert webhook_to_donation(event).amount_cents == 7500

def test_refund_is_unsupported(event):
    event['type'] = 'charge.refunded'
    with pytest.raises(UnsupportedEvent):
        webhook_to_donation(event)

def test_cli_exit_code(tmp_path):
    proc = subprocess.run([sys.executable, '-m', 'tools.cli', 'transform', str(tmp_path / 'missing.json')])
    assert proc.returncode == 2
